INSERT INTO theory_content (chapter_slug, subject_id, concepts_json) VALUES ('telangana-history-en-chapter4-vishnukundis', 'telangana-history-en', '') ON CONFLICT(chapter_slug) DO UPDATE SET concepts_json = '';
UPDATE theory_content SET concepts_json = concepts_json || '[{"partNumber": 1, "conceptId": "telangana-history-en-chapter4-vishnukundis-p1", "partName": "Overview", "bodyMd": "The Vishnukundis (Vishnukundins) hold a primary place among the important royal dynasties of the Andhra-Telangana region, not merely for spreading its name and fame but for introducing new practices in religion, language, and culture. Starting as feudatories in the Krishna-Godavari region, they eventually extended their empire up to the Narmada river and, for a time, ruled the territory between the three seas — the Arabian Sea, the Bay of Bengal, and the Indian Ocean. For nearly 210 years, between 358 CE and 569 CE, they ruled primarily over Telangana and northern Andhra lying north of the Krishna river.\n\nThey were originally feudatories of the Ikshvakus, and their kings called themselves “Amarpuriswaras” or “Lords of Amarapuram.” Their political stint began on the northern bank of the Krishna river, in the districts of present-day Nalgonda and Mahabubnagar in Telangana. The second king, Madhava Varma, married a Vakataka princess and thereby secured his kingdom. Seventeen Vishnukund kings ruled Andhra Pradesh for about 260 years; the lion springing forward (a pouncing lion) was the royal emblem of the dynasty.\n\nThe first few Vishnukund rulers were Buddhists; later rulers adopted the Vedic (Brahmanical) faith. During their time, Sanskrit and spoken Telugu were both in use as administrative/literary languages. In Andhra political history, it is their cultural history — even more than their political history — that stands out as their most glorious legacy. Politically, they established a strong independent kingdom in Andhra for roughly a century and a half; on one side they gained prominence through marriage alliance with the powerful Vakataka emperors, and on the other, through warfare, they subdued the Kalinga chieftains. Their reign also holds a distinct place in the religious history of Andhra.", "free": true}, {"partNumber": 2, "conceptId": "telangana-history-en-chapter4-vishnukundis-p2", "partName": "Capitals", "bodyMd": "The Vishnukunds had their capitals at **Amarapuram, Indrapalanagaram, and Dendaluru**.\n\n*   **Amarapuram** is identified with Amrabad, the present-day mandal headquarters in Mahabubnagar district.\n*   **Indrapalanagaram**, also called **Sukrapuram**, is located on the outskirts of Tummalagudem village in Valigonda mandal of Nalgonda district.\n*   **Dendluru** is located near Pedavegi in West Godavari district.\n*   There is also some indication that a place between Bezawada (Vijayawada) in Andhra Pradesh may have served as a Vishnukund capital for some time.\n*   Another capital, known as **Puranisangamam**, could be either Sanganigundala in Amrabad mandal or Sangameswaram near Alampuram; the ruins of an erstwhile town lie on the outskirts of Medimankal village near Sanganigundala.", "free": true}, {"partNumber": 3, "conceptId": "telangana-history-en-chapter4-vishnukundis-p3", "partName": "Sources for Vishnukund History", "bodyMd": "The main sources for the study of Vishnukund history are **inscriptions**. The dynasty''s history is known not only from **13 epigraphs issued during their own period**, but also from **8 further inscriptions issued in the later period** — 21 inscriptions in all, of which **16 are copper plate inscriptions and 5 are stone inscriptions**.\n\n**Inscriptions issued during the Vishnukund period:**\n\n| Name of the Inscription | Region |\n|---|---|\n| Tummalagudem Copper plates (2) | Valigonda Mandal, Nalgonda district |\n| Chaitanyapuri stone inscription | Hyderabad, Rangareddy district |\n| Keesaragutta stone inscription | Amrabad Mandal, Mahabubnagar district |\n| Saleswaram stone inscription | Sattenapalli, Guntur district |\n| Velpuru Stone inscription | Tenali, Guntur district |\n| Ipur Copper plate inscriptions (2) | Visakhapatnam district |\n| Ramatirtham Copper plate inscription | Tuni, East Godavari district |\n| Chikkulla Copper plate inscription | Tuni, East Godavari district |\n| Tundi Copper plate inscription | Ramachandrapuram, East Godavari district |\n| Polamuru Copper plate inscription | Satara district, Maharashtra |\n| Khanapur Copper plate inscription | Satara district, Maharashtra |\n\nBesides inscriptions, the **coins** issued by the Vishnukunds, fort walls, cities, and cave temples they built, and objects, tools, and sculptures unearthed in excavations all aid in reconstructing their history. Writings of the period, such as **Janasraya Chhando Vichchitti** and **Sethubandha**, also help in understanding the historical developments of those times.", "free": false}, {"partNumber": 4, "conceptId": "telangana-history-en-chapter4-vishnukundis-p4", "partName": "Political Developments", "bodyMd": "The decline of the Ikshvakus and the subsequent Pallava expansion paved the way for the rise of Vishnukund independence.\n\n*   Till **355 CE**, the Ikshvakus ruled districts in the middle of Andhra Pradesh, with Vijayapuri (Nagarjunakonda) as capital, lying on both sides of the Krishna river.\n*   The Ikshvakus were defeated by the **Pallavas of Kanchi**, who brought the Krishna river region up to Srisailam under their control.\n*   In **358 CE**, the Gupta king **Samudragupta**, ruling from Pataliputra, defeated the Pallavas in his victorious southern expedition and returned north.\n*   Taking advantage of this, the **Anandagotrins (Kandara kings)** — earlier feudatories of the Ikshvakus in the Krishna-Guntur region — and the **Salankayanas** in the Vengi region (Eluru) declared independence. In Telangana, the **Vishnukundins** became independent.\n\nFrom then, the Vishnukunds ruled the Telangana region for some time (first half of the 5th century CE) and the Maharashtra area for nearly 200 years. \n\n**Vishnukund Rulers (widely accepted chronology):**\n\n| No. | Ruler | Reign |\n|---|---|---|\n| 1 | Indra Varma | 358 – 370 CE |\n| 2 | Madhava Varma I | 370 – 398 CE |\n| 3 | Govinda Varma | 398 – 440 CE |\n| 4 | Madhava Varma II | 440 – 495 CE |\n| 5 | Deva Varma | 495 – 496 CE |\n| 6 | Madhava Varma III | 496 – 510 CE |\n| 7 | Vikramendra Varma I | 510 – 525 CE |\n| 8 | Indrabhattaraka Varma II | 525 – 555 CE |\n| 9 | Vikramendra Varma II | 555 – 569 CE |\n\nMadhava Varma II is noted to have \"taken Vakataka\" — i.e. absorbed Vakataka territory — from Prithivishena. **Manchanna Bhattaraka** is also said to have ruled for some time around 570 CE in the Amrabad region.\n\nThe first two kings began their political career in south Telangana, in the Mahabubnagar and Nalgonda districts, which made it easier for later kings to expand the territory.\n\n### Govinda Varma (398–440 CE)\n\n*   **Expansion:** Expanded the Vishnukund kingdom on both sides of the Sriparvata (Srisailam–Nagarjunakonda) region through his physical prowess; occupied territory up to the Gundlakamma river by defeating the Pallavas.\n*   **Alliance:** Married the daughter of a powerful local chief, Mularaja of Gunapasapuram in coastal Andhra. With his help, Govinda Varma defeated the **Salankayanas of Vengi** and annexed their kingdom.\n*   **Northern gains:** Areas on the other side of the Musi river also came under his kingdom.\n*   **Evidence:** A stone inscription of his time was found at Chaitanyapuri in Hyderabad; Vishnukund fort and temple remains survive at Keesaragutta on the outskirts of Hyderabad.\n*   The **Kesari vagu** (stream) below Keesaragutta gave the surrounding area the name **Gattukesari**, now called Ghatkesar — \"Kesari\" means lion, the royal Vishnukund emblem. A royal seal bearing this emblem was recently found at Keesaragutta.\n\n### Madhava Varma II (440–495 CE) — the greatest of the Vishnukund kings\n\n**Military career**\n\n*   Fought and won more than **100 battles**; as a mark of victory in each battle, he installed a Sivalinga at Keesaragutta.\n*   Built a **Ramalingeswaraswamy temple** at every place he won a battle — these temples at Velpuru (Sattenapalli taluk, Guntur district), Ipur, Indrapalanagaram, and Keesaragutta still receive worship today.\n*   With the help of his relative **Prabhakara**, ruler of Gunapasapuram, occupied Kalinga (northern coastal Andhra and south Odisha).\n*   In his **33rd regnal year**, attacked the Pallavas again and expanded the kingdom up to the Gundlakamma river.\n*   In the west, defeated **Prithvisena**, the last ruler of the main Vakataka line (460–480 CE), and married his daughter — a marriage that secured Vakataka territory for the Vishnukunds.\n\n**Extent of empire:** With these victories, Madhava Varma II''s empire extended from the Bay of Bengal in the east to the Arabian Sea in the west, and from the southern ocean (perhaps Pulicat Lake) in the south to the Reva (Narmada river) in the north. Many feudatories submitted to him; one of his inscriptions was found in Maharashtra, and Vishnukund coins have been found across Maharashtra.\n\n**Epithet and capital shift:** He bore the epithet _''**trivara nagara bhavnagata sundari hridaya nandana**''_ (\"the one who brought happiness to the beautiful maidens living in the buildings of the city of Trivara\"). The identification of Trivaranagaram remains debated — among the possibilities suggested are Tripuri/Tevar near Jabalpur on the Narmada, and a capital in the South Kosala or northern Kalinga region — but it is clear his kingdom extended to the Narmada and Mahanadi rivers in the north.\n\nBecause the Vishnukunds and Pallavas were perpetually at war, Madhava Varma II shifted his capital to **Denduluru**, near Vengi, to better guard against Pallava invasions. He also strengthened the walls of **Amarapuri**, his original capital, and appointed his eldest son, **Deva Varma**, as royal representative there.\n\n**Sacrifices:** To announce his victories, Madhava Varma II performed **11 Ashvamedha sacrifices, 16 Rajasuya sacrifices**, and a thousand other sacrifices such as Vajapeya and Purushamedha. It is said he authored a book on metre (Chandas) titled _**Janasraya Chandovichhitti**_, beginning with the title \"Janasraya.\" \n\n### Vikramendra Varma I (510–525 CE)\n\n*   Succeeded his father Madhava Varma II.\n*   Known as _''**Vishnukundi Vakataka Vamsadwayalankara Janma**''_ — one born of both the Vishnukund and Vakataka lines, since his father was Madhava Varma II and his mother Vakatadevi was of the Vakataka family.\n*   Held the title **''Mahakavi''** (great poet).\n*   Taking advantage of Vikramendra Varma''s literary preoccupations, **Madhava Varma III**, son of Deva Varma, declared independence at Amarapura. This Madhava Varma completely exterminated the **Kandara (Anandagotrika) dynasty** and assumed their title, _''Trikuta Malayadhipa''_.\n*   Vikramendra Varma — whether driven from the Vakataka throne or arriving from his capital Denduluru — suppressed Madhava Varma III and ruled the Vishnukund kingdom for about **15 years (510–525 CE)**.\n\n### Indra Varma II (525–555 CE)\n\n*   Succeeded Vikramendra Varma I; was attacked by Madhava Varma III with the help of the Chalukyan king **Pulakesi** (the title _''Ranavikrama''_ of Pulakesi found at Yeleswaram supports this). Because of this association, the Chalukyas — like the Vishnukunds — began using titles containing the word _''asraya''_.\n*   Defeated Madhava Varma II''s other relatives (Palivandlu) and may have merged the Amarapuri kingdom into his own territory, called _''Rajakshetram''_.\n*   **Kalinga alliance:** The Kalinga feudatories formed an alliance against Indra Varma II in the northeast; Indra Varma II emerged victorious and saved his kingdom.\n*   **Setback:** The Maukhari king **Esana Varma** of North India claimed to have conquered the Salika and Andhra kings, indicating that in his southern campaign Esana Varma defeated Indra Varma II. To restore friendly relations, Indra Varma II gave his daughter **Indrabhattarikadevi** in marriage to **Sarva Varma**, son of Esana Varma, and maintained friendship with them thereafter.\n\n### Vikramendra Bhattaraka Varma (555–569 CE)\n\n*   After Indra Varma II''s death, his minor son Vikramendra Bhattaraka Varma was placed on the throne by the council of ministers. His epithet _''**Sakala Bhuvana Rakshabharanaikasraya**''_ suggests the vast extent of his kingdom.\n*   In his **11th regnal year**, the Pallava king **Simhavarama** attacked the Vishnukund kingdom; the battle took place around **566 CE** near Dhanyakataka in Guntur district. Vikramendra Varma II won this battle with the help of **Prithivimula**, and as a mark of the victory made donations to the _Vihara_ of Paramabhattarika Devi at Indrapalanagaram.\n*   At the same time, **Prithvimaharaja** declared independence at **Pishtapuram**; the districts of Godavari, Khammam, and Nalgonda were then under his kingdom.\n*   Vikramendra Varma II later attacked Prithvimaharaja after gathering his army, but **died in this battle**. With his death, the Vishnukund dynasty disappeared within a short span.\n\n### Decline\n\n*   With Vikramendra Varma II''s death, **Prithvimula** also became independent and ruled the Godavari district areas.\n*   From the decline of the Vishnukund kingdom (**569–590 CE**) for about half a century, up to **617 CE**, **Prithvimaharaja** ruled south-eastern Andhra and **Prithvimularaja** ruled the Guntur-Krishna and Godavari districts.\n*   Both were defeated in **617 CE** by **Pulakesi II**, the Badami Chalukya ruler, who thereby extended his kingdom into the Telangana and Andhra areas.", "free": false}, {"partNumber": 5, "conceptId": "telangana-history-en-chapter4-vishnukundis-p5", "partName": "Administrative System", "bodyMd": "*   Though the Vishnukunds acquired their kingdom through their own prowess and strength, their inscriptions state that they gained the authority to rule by serving at the feet of **Sriparvataswamy**, and they carved the word \"Sriparvata\" on their coins — reflecting a stated humility and loyalty.\n*   They earned fame for proper and popular rule: monks, orphans, beggars, the diseased, and the distressed could earn a living justly under them. They extended protection to Brahmins, giving them lands, villages, and posts, and donated servants, cots, chariots, travel equipment, food, water, buildings, jewellery — and girls — to establish name and fame among the poor.\n*   **Extent of rule:** After the Satavahanas, the Vishnukunds are credited as the next dynasty to rule an extensive empire in the Deccan. For nearly 50 years, Maharashtra, Telangana, and Andhra Pradesh were under their rule, though Telangana and coastal Andhra north of the Krishna remained under them for a longer period.\n*   **Titles:** Because of ruling such a vast empire, they assumed the title **''Maharaja''**; because they protected all types of people they also adopted titles such as _''Sakala Bhuvanaikasraya, Janasraya, Satyasraya, Uttamasraya,_ and _Vikramasraya''_. This set an example for later dynasties — the later Chalukyas wore _''asraya''_ titles, and the Kakatiyas refer' WHERE chapter_slug = 'telangana-history-en-chapter4-vishnukundis';
UPDATE theory_content SET concepts_json = concepts_json || 'red to Madhava Varma as their dynastic founder; the kings of Pithapuram and the Velamas made the same claim.\n*   **Legal system — ''Divyalu'':** Madhava Varma is said to have discovered the legal duties known as _''**Divyalu''**_. When a prince''s chariot accidentally killed the son of a tamarind-selling woman, Madhava Varma imposed the death sentence on the prince. Tradition holds that Malliswaraswamy, pleased by this justice, made gold rain at Bezawada and restored life to both the prince and the boy — a story also found in later literary works such as _Nachiketopakhyanam, Prabhodha Chandrodayam,_ and _Panchatantram_.\n*   **Territorial divisions:** The kingdom was divided into Provinces (**Rashtra**), Provinces into **Vishayas**, and Vishayas into villages. A Rashtra was governed by a **Rashtrika**. Known Rashtras include Paraki Rashtra, Plekki Rashtra, Karma Rashtra, and Kalinga Rashtra. A **Vishaydhipati** was the governing head of a Vishaya; known Vishayas include Grudhranadi Vishaya and Netrapati (Natavadi) Vishaya.\n*   The practice of appointing the king''s son as **''Yuvaraja''** for part of the kingdom existed. Some feudatory states remained subordinate to the Vishnukund kingdom, and matrimonial relations were formed with some of them, who in turn helped protect and extend the kingdom.\n*   The king was assisted by the **Yuvaraja, Mahamatya, Amatya**, an Intelligence Officer, a Secret Adviser, and other officials.\n*   **Forts:** Vishnukunds built several forts, often named for meanings similar to Amarapuram, their first capital — e.g. Indrapalanagarm (Ramannapet taluk, Nalgonda district), Indrakeeladri at Bezwada, and Indur in Nizamabad. To guard their capital from Pallava invasion, they built the **biggest fort in the Andhra-Telangana region** in the Amrabad area, whose wall stretched around **200 kilometres**; construction of this wall was continuous, giving rise to a local saying comparing any long-running house-wall construction to \"the construction of Patalabhadruni fort.\"", "free": false}, {"partNumber": 6, "conceptId": "telangana-history-en-chapter4-vishnukundis-p6", "partName": "Economic Development", "bodyMd": "*   Villages of the Vishnukund period had a **self-sufficient economy**, with farmers and other occupational groups depending on one another.\n*   Besides agraharas, Brahmins were also donated farmers, and servants and maid servants, to cultivate land; Brahmins with knowledge of the seasons developed agriculture with the help of these servants, bringing new lands under cultivation.\n*   Inscriptions record that the Vishnukunds dug many wells and tanks for agriculture, through which wet crops were cultivated. Land was measured in terms of **nivartanas**.\n*   **Domestic trade:** Vishnukund coins are found at Yeleswaram, Bhuvanagiri, and Sultanabad (Karimnagar district) in Telangana; at Bojjannakonda and Elamanchili (Visakhapatnam district) in Andhra Pradesh; and at Nasik, Khanapur, Nagpur in Maharashtra, and Brahmagiri in Madhya Pradesh — indicating a network of internal trade.\n*   **Foreign trade** grew after the occupation of Vengi from the Salankayanas and of the Kalinga kingdom. More Vishnukund coins found in coastal Andhra, ship marks on the coins, and Madhava Varma II''s title _''trisamudradhipati''_ (\"lord of three seas\") all point to the importance of foreign trade.\n*   Foreign trade was carried on from eastern coastal ports such as **Motupalli and Kodur** with eastern countries — Burma, Siam, Cambodia, China, Japan, Ceylon, Sumatra, Java, Borneo, Malaya, Arakan — and western countries — Egypt, Rome, Greece.\n*   Vadapalli, Bezawada, Amaravati, Motupalli, Ghantasala, Koduru, and Alampuram-Kudalisangamam on the banks of the Krishna mainly carried on international trade, occasionally taking up foreign trade as well.\n*   In excavations at **Kudali Sangameswaram near Alampur**, a **gold coin of the Roman Emperor Constantine (306–337 CE)** was discovered along with other coins, showing that the Krishna-Tungabhadra doab was a centre for foreign trade even before the Vishnukund period, continuing through it.\n*   The Chinese traveller **Fa-Hien** recorded that shells were also used as currency in the Vishnukund kingdom in the early 5th century CE. Another Chinese traveller, **Huien-Tsang**, wrote of full-size golden Buddha statues at Sriparvata (not found), though copper Buddha statues (4th–5th century CE) measuring one to five inches have been found at Buddham and Amaravati, indicating skilled carpentry/craftsmanship. A cast-iron snuff box shaped like a mango bud, measuring 7 cm, found at Keesaragutta, is further testimony to this craftsmanship.\n*   Inscriptions state that sufficient wealth existed for monks, Brahmins, orphans, beggars, the diseased, and the poor to lead a justly-earned life — indicating a strong economy for the period.", "free": false}, {"partNumber": 7, "conceptId": "telangana-history-en-chapter4-vishnukundis-p7", "partName": "Social Conditions", "bodyMd": "*   Vishnukund inscriptions state that \"they adhered to the _varnasramadharma_, which is associated with giving gifts and donations.\" **Govinda Varma** in particular is said to have respected varnasramadharma, and the Vishnukunds tried to ensure that all four varnas — brahmana, kshatriya, vaisya, and sudra — followed their professional duties, though the first two castes seem to have held greater respect.\n*   The importance of the brahmana and kshatriya castes is reflected in the title **''parama brahmanya''** borne by some Vishnukund rulers, and in their assumption of \"brahma-kshatra\" brilliance through performing the **hiranyagarbha** sacrifice. This indicates that the Vishnukunds, who had originally been Sudras, rose in status through performing many sacrifices, and gave many agraharas to Brahmins while also honouring higher-caste members with official posts.\n*   **Vaisyas** were engaged in internal and external trade. Among the Sudras, **carpenters, sculptors, and handloom weavers** held a rightful place.\n*   **Kanyadanas** (offering girls in marriage) made the families of both bride and groom happy; the Vishnukunds also donated items needed for daily life — sleeping, sitting, drinking, eating — and buildings and jewellery. That Madhava Varma is said to have always served at the feet of his parents suggests that reverence for parents and elders was valued in the society of the time.", "free": false}, {"partNumber": 8, "conceptId": "telangana-history-en-chapter4-vishnukundis-p8", "partName": "Cultural Development", "bodyMd": "The Vishnukunds were followers of the **Vedic religion**, with **Sriparvataswamy** as their family deity; their names reflect Vedic affiliation, and titles such as **''Paramamaheswara''** and **''Parama Brahmanya''** indicate devotion to Siva and to Brahmanical religion.\n\n*   Before the Vishnukunds became independent rulers, the Allahabad inscription issued by Samudragupta used the phrase _''Paramabhattaraka Padanudjyatasya''_, which closely resembles _''Sriparvataswami Padanudhyatasya''_ in the Vishnukund inscriptions.\n*   The name **''Paramabhattarikadevi''**, wife of Govinda Varma (the first-generation Vishnukund king), also resembles the name of a Gupta goddess. Tradition connects Sriparvataswamy/Srisaila Mallikarjuna Swamy with **Chandravati (Sandravati)**, said to be the daughter or sister of King Chandragupta. The ruins of the Guptamaheswara temple, said to have been installed by her, stand even now to the north of the Umamaheswara temple and below the Prataparudra fort.\n*   It appears that after Madhava Varma II married Vakatakadevi, the Vishnukunds did not patronize religions other than Vedic-Brahmana religion — the Vakatakas being relatives of the Guptas. On the whole, the influence of the Guptas and Vakatakas led the Vishnukunds to become sanskritised followers of Vedic-Brahmana religion.\n\n### Vedic-Puranic Religion\n\n*   Though the Vishnukunds patronized Buddhism (very popular in the 4th–5th centuries CE), it appears they made greater donations to Brahmins, remaining in reality followers of Vedic and Puranic religion. All their names relate to the Vedic and Vaishnava faith.\n*   **Indrabhattaraka Varma** and his son **Vikramendra Varma** assumed the title **''Parama Maheswara''**. The Vishnukunds acknowledged that they gained authority to rule through _''Sriparvataswamy Padanudhyanam''_ (worshipping at the feet of Sriparvataswamy), and carved the word \"Sriparvata\" on their coins.\n*   At Sriparvata _padam_ (foot), in Amrabad mandal, is the (Uma)Maheswara temple, which became famous as the northern gateway of Srisaila Devasthanam; **Srisaila Mallikarjuna** also became a popular name during Vishnukund times.\n*   In his **33rd regnal year (489 CE)**, Madhava Varma II ordered the installation of a war-drum idol and of **Dantamukhaswamy (Ganapati)**; a Venkaiah (Ganapati) idol outside Amrabad village, along with the Venkaiah _bavi_ (well) and the ruins of a Siva-Parvati temple, and Ganeswara temple in the nearby hills, are connected to this. The war-drum is now kept in the Umamaheswara temple compound.\n*   Inscriptions record that **Govinda Varma constructed several ''divyatanas''** (shrines). Vishnukund temples were located in their early capital in Amrabad mandal, in the valleys of the Nallamala forests, under waterfalls, and in caves.\n*   The **Anandagotris (Kandara kings)**, contemporaries of the Vishnukunds who ruled areas east of the kingdom, worshipped ''Sambhu'' at Vanakeswaram (in Amrabad mandal).\n*   **Akkanna-Madanna caves and temples**, though popularly attributed to the historical figures Akkanna and Madanna (17th century CE), were in reality built by **Madhava Varma II** — including the Akkanna-Madanna caves in the Kanaka Durga group of temples on Indrakeeladri at Bezwada, the temples at Keesaragutta, and the Maheswara temple on the outskirts of Hyderabad. Because of similarities in promoting Hinduism, the name of Madhava Varma appears to have been mistakenly attributed to Akkanna-Madanna.\n*   Madhava Varma II built many **Ramalingeswara temples**, one for each battle won — at Velpuru (Sattenapalli taluk, Guntur district), Ipur, and Keesaragutta, still worshipped today. To the southeast of the Umamaheswara temple at Amrabad, footprints of Rama are found; to its north is the **Pallaveswara temple**, built by the Pallavas — who attacked the Vishnukunds two or three times — as a mark of their own victory. As the Vishnukunds were Vaishnavas, their Sivalingas are called **Ramalingas**; the same practice of dedicating temples to victories was later followed by the Eastern Chalukya king **Vijayaditya II**, who built 108 Bhimeswara temples to mark his 108 victories.\n*   Madhava Varma II was described as _''**Snanapunyodaka pavitrikrita sirshah**''_ (\"the one whose head was purified by the sacred waters\"), showing the growing importance of pilgrimage and ritual bathing during his time.\n*   **Vikramendra Varma** donated Regonta village as _devabhoga_ to the Triyambakanatha temple (God Somagiriswaranatha) in Netrapati vishaya. The Vishnukunds donated villages, lands, old chariots, horses, cows, cots, arts, water, and food along with these grants.\n*   Madhava Varma II performed numerous sacrifices and rituals — _Ekadasaswamedha, Avabritha, Avodhauta, Jagatkalmasha, Agnistoma, Bahuswarna, Purushamedha, Vajpeya Shodarajasuya, Prajapatyaneka Paundarika Sata Sahasrayojino_. The practice of donating thousands of servants and girls, and of sacrificing men in the yajnas, reflects prevailing social inequalities of the time. The **avabritha bathing ghat** at Munnanoor fort remains a memory of these sacrifices.\n\n### Buddhism\n\nBy the first phase of Vishnukund rule, Buddhism had spread widely in society; early Vishnukund rulers, while themselves Vedic followers, patronized Buddhism to respect majority opinion.\n\n*   **Govinda Varma**, in his 37th regnal year, on the full moon day of Vaisakha month, donated resources for light, sandal flowers, dhwaja water, food, sleep, _arama_, _grasa_, and medicine to the _mahavihara_ built by his queen **Paramabhattarika** at Indrapalanagara, addressed to **Dasabalabali**, well-versed in the 18 branches of Buddhist _Dharma_, for the 14th Arya Sangha at Penkaparra village. He also donated the village of Enmadala to the same sangha.\n*   **Vikramendra Varma** donated Irrundero village in 566 CE for the enjoyment of monk sanghas at the same vihara.\n*   Govinda Varma''s uncle **Prithivimula** built a _mahavihara_ named Tokhalikhata at the capital Gunapasapuram (East Godavari district). His son **Harivarma** built another _mahavihara_ at Gunapasapuram, donating Kattacheruvu village to it, and also built a **Sekya bhikshu vihara** near Tatikonda.\n*   Inscriptions indicate that Vishnukund kings likely built or extended Buddhist _arama-viharas_ on all sides of their kingdom. Surviving proof includes the **Govindaraja vihara** at Chaitanyapuri (Hyderabad); Buddhist ruins at Keesaragutta and Kondapuram; _arama_, _stupa_, _viharas_ at **Phanigiri** and Gajulabanda in Nalgonda district; and _stupas, aramas_ at Nelakondapalli in Khammam district.\n*   At **Phanigiri**, excavations in 2011 revealed six _aramas_, each with several rooms. Buddhist sites also existed at Jaggayyapeta, Salihundam, Ramatirtham, Thotlakonda, Bojjanakonda, Buddham, and elsewhere in Andhra Pradesh, though most predate the Vishnukunds — the dynasty is credited with major extension activity at these sites during its period. **Saleswara vihara**, in Amrabad mandal, Mahabubnagar district, built originally during Ikshvaku times, shows brick structures and Brahmi-script inscriptions of the Ikshvaku period alongside later Telugu-Kannada script inscriptions.\n*   The **Hinayana** sect was present at Chaitanyapuri, Hyderabad, where a Prakrit inscription in six rows records that **Bhadanta Sanghadeva** built a rock house for those offering sandal and clothes to the Govindaraja vihara. This Chaitanyapuri inscription, dated to the beginning of the 5th century CE, is the most ancient inscription found in the Hyderabad region.\n*   At **Keesaragutta**, traces of **Mahayana** Buddhism survive, including a metal statue of Mahayana founder **Acharya Nagarjuna**, collected by historian Sri Kurra Jitendrababu; the hood of a snake over the sitting figure''s head recalls the iconography also associated with the 23rd Jain Tirthankara, suggesting that Jainism may also have flourished in the Keesaragutta region.\n*   The inscription mentions **Pindapatikula**, a special branch of Hinayana Buddhism, and states that there were **18 branches of Buddhism**, with Dasabalabali being learned in all of them. There were several _sanghas_ within these branches; the **14th Arya Sangham** was one. For **Asanapura Arya Sangham**, Vikramendra Varma had the **Trilokesraya Rajamahavihara** constructed, and for its representative Sanghadasa, donated two villages with their gardens. Vikramendr' WHERE chapter_slug = 'telangana-history-en-chapter4-vishnukundis';
UPDATE theory_content SET concepts_json = concepts_json || 'a Varma bore Buddhism-related titles of **Mahabodhisatva** and **Paramasaugata**; Sanghadasa belonged to the Kshemacharya branch, associated with Tamraparni (Sri Lanka).\n*   The Vishnukunds were the **last Telugu kings to patronize Buddhism**. By the end of the 5th century CE, south of the Krishna river in the Amaravati/Nagarjunakonda region, the **Vajrayana** branch had emerged, into which women, wine, non-veg, and deceitful _mantras_ entered, gradually losing purity — such places (Bomkur, Chinna Bomkur, Pedda Bomkur, Lanjaladugu near Jaggayyapeta) became associated with decline.\n*   Another development was growing **Brahmin influence within Buddhist sanghas and arama-viharas**, reflected in the phrase _''Anantha brahmana sambharasya''_ in Govinda Varma''s inscription. Brahmins gradually depicted Buddha as the ninth _avatara_ of Vishnu, and some Buddhist centres turned into Vaishnava (Narasimha) centres — Dharmapuri (Karimnagar district), originally Buddhist, came to have temples of Ramalingeswara Swamy and Narasimha Swamy.\n*   The last great Buddhist philosophers lived in the Vishnukundin kingdom: **Dingnaga**, a 5th-century logician, debated with **Isvarakrishna** (author of _Sankhya Karika_) at Vengi. Kalidasa''s _Meghasandesam_ indicates Dingnaga lived for a time at Ramagiri (Ramagundam) and Munulagutta (near Kotilingala) in Karimnagar district; he authored over a hundred books, the famous _Pramana Samuchchayam_ among them, written in Sanskrit, and taught the Yogachara school — he was the last of the great Buddhist scholars of Telugu country. A stupa and small inscriptions at Basara also indicate his presence there for some time.\n\n### Jainism\n\n*   A Kannada literary work, **Dharamarutam** (1115 CE) by the Jain poet **Nayasena**, explains that the name \"Sriparvata\" derives from **Sridharamuni**, brother of the Ikshvaku king Priyabala who ruled Vengi country from Pratipalapuram. According to this text, gods worshipping him gathered at a place thereafter called Amaravati; sky-gods showered jasmine flowers on him while he meditated under an _Arjuna_ (Maddi) tree, giving rise to the name **Mallikarjunam**.\n*   Corresponding places are found in Amrabad mandal, Mahabubnagar district — Vataverlapalli near **Mallela Tirtham**, identified with Mallikarjunam; the **Pulumavi inscription** (Nasik, first half of 2nd century CE) mentions a place \"Siridhan,\" possibly named after Sridharan.\n*   Jain _rushis_ are called \"munulu\"; the place where Sridhara and other Jain _munis_ meditated may have become \"**munuluru**\" — now Munnenoor (Munnanoor), also in Amrabad mandal. The text further states that minister **Indraprabhudu** brought Sridhar to Rishinivasa area and made him administrator there for a time as the king of Vengi; since Indra Varma was the first Vishnukund king, he may have been appointed by Sridharudu as administrator of the Amrabad area.\n*   **Prithvimula**, father-in-law of the first-generation Vishnukund king Govinda Varma, is recorded making donations to the **Jain vihara at Vardhamanu**, further indicating Jain influence of the period. To the east of Umamaheswaram stood the temple of **Mukmiridani**, and **Mukmirapet** near Munulagutta in Vellatur mandal, Karimnagar district — Mukmiri appears to have been a Jain-related goddess.\n*   Jainism disappeared during the Vishnukund period itself. The **Kapalika sect**, which arose during those days — practising magic, mantras, illicit relations with women, drinking, and vulgar dancing — lost popular favour and became responsible for the decline of Jainism; Jain temples were converted into Saiva temples, Srisailam itself being cited by Nayasena as a prime example.\n*   It is recorded that **Kumarilabhatta**, an Andhra born at Jayamangala village on the bank of the Mahanadi in Kalinga (Odisha), received Jain education in his youth but later condemned Jainism, attracting many Jains toward Vedic religion. Among those who shifted from Jainism to Vedic religion, **Indra Varma**, the first Vishnukund king, may also have been one.", "free": false}, {"partNumber": 9, "conceptId": "telangana-history-en-chapter4-vishnukundis-p9", "partName": "Literary Development", "bodyMd": "*   The Vishnukunds established **ghatikasthanas** (centres of learning) and patronized Vedic studies; study of the **Vedas** and reverence for Brahmins are recorded in the inscriptions. Brahmins who studied the Vedas were given agraharas — inscriptions record names such as **Agnisarma** and **Easwarasarma** among the recipients.\n*   **Ghatikesari**, the suburb of Hyderabad, is understood to have been the Ghatikasthana of the Vishnukunds, supported by structures of the Vishnukund period unearthed near Keesaragutta. Those who received agraharas were well-versed in education and literature; **Dasabalabali**, the Buddhist guru, is recorded as learned in the four Vedas, adept in all sciences, and versed in all 18 Buddhist _dharmas_.\n*   Several kings were themselves scholars, as reflected in their titles:\n    *   **Govinda Varma** — _''Shadabhigna''_\n    *   **Vikramendra Varma** — _''mahakavi''_ and _''parama sogatasya''_ (as enlightened as Buddha)\n    *   **Indrabhattaraka Varma** — _''ghatikavapta punyasancharya''_\n    *   **Madhava Varma II** — _''vidyadvijaguru vipravruddh tapasvi janasraya''_These titles show the Vishnukund kings were themselves writers and scholars as well as patrons of poets and scholars.\n*   **Sanskrit replaced Prakrit as the state language** during the Vishnukund period. As Buddhism declined, Prakrit — its associated language — also disappeared; notably, the Chaitanyapuri inscription of Govinda Varma, connected to Buddhism, is in Prakrit, while all later inscriptions were issued in Sanskrit.\n*   The language of the common people, however, remained **Telugu**. In the Chikkulla inscription of Vikramendra Varma (in Sanskrit), the phrase _''vijaya rajya samvatsarambul''_ appears, in which \"ambul\" is a Telugu word — showing the influence of Telugu (with \"l\" used for \"lu,\" and \"ambu/bu\" for \"mu,\" as an earlier form of \"samvatsaralu\"). Village names recorded in Vishnukund inscriptions are entirely Telugu.\n*   Telugu terms surviving from Vishnukund inscriptions include Kudavada, Velimbali, Marokaki, Kalika, Puranisangama, Peruvatika, Dendulur, Ravareva, Regosam, Penkapara, Irundero, Tundi, Paraki, Vishayam, Netrapati, Vishaya, and _''toluchuvandhu''_ — a pure Telugu word carved on a boulder at Keesaragutta.\n*   The Sanskrit poetic work _''Janasrya chhando vichhitti''_ shows references to the Telugu language and is felt to have been authored by **Madhava Varma II**, based on his title _''janasraya''_ — though some scholars attribute it instead to a person named **Ganaswamy**, since the book''s actual preface is not available. Its fifth chapter deals with Telugu _Kavitvam_ — _ganas, yatulu, praralu, jati padyalu_, and _dvipada/tripada_ verses. The word _''janasraya''_ also appears in _''kavijanasrayam''_, a Telugu metre work written by **Malliya Rechana** in the early 10th century CE, whose roots lie in this earlier work.", "free": false}, {"partNumber": 10, "conceptId": "telangana-history-en-chapter4-vishnukundis-p10", "partName": "Development of Architecture and Sculpture", "bodyMd": "*   Structures of the Vishnukund period demonstrated a new architectural style. Their capital cities, caves, temples, and _arama-viharas_ became key sources for the study of this architecture.\n*   In Telangana, Vishnukund forts survive in their capitals of Amaravati (Amrabad), Indrapalanagaram, and Keesaragutta. Below Keesaragutta and adjoining the tank, spacious brick buildings, palaces, Siva temples, and Shakti temples — around 1500 years old — still show their brilliance, containing _garbhagriha, arthamandapam,_ and _mukhamandapam_ like present-day temples. On the walls of **Bhuvanagiri fort**, sculptures of the royal Vishnukund emblem — the pouncing lion — are found, suggesting the fort was originally built by the Vishnukunds.\n*   Buddhist _viharas_ and _aramas_ built by Vishnukund kings, royal relatives, and wealthy persons are found mainly at Chaitanyapuri (Hyderabad), Indrapalanagaram, Phanigiri, Tirumalgiri, and Gajualabanda in Nalgonda district, and Nelakondapalli in Khammam district.\n*   **Govindaraju** built a Raja _vihara_ at Chaitanyapuri; his queen **Paramabhattaraka Mahadevi** built a _vihara_ at Indrapalanagaram known as the Paramabhattarika Mahadevi vihara — recent excavations near this vihara have identified sculptures of Buddhist _acharyas_ carved on caves at two locations.\n*   Excavations at **Phanigiri** revealed sculptures depicting Buddhist Jataka stories, Buddha''s footprints, chaityas, stupas, and monks'' _aramas-viharas_ and _mantapas_. The Buddhist _stupa_ at **Tirumalagiri**, viewed from above Phanigiri, appears in the seeming distance; the Buddhist _stupa_ at **Nelakondapalli** was so large it was called **Virat stupa**, later corrupted to **Virata Raju Gadde**. Marble sculptures of Buddha and metal statues have been recovered from these excavations.\n*   **Chaitya decorations** of the Vishnukund period appear on _mantapa_ pillars found on caves at L. Madugu (near Manthani town, Karimnagar district) and on caves at Gaurigundam waterfall — considered Buddhist _Aramas_. The **Komati caves**, below L. Madugu, are believed to have served as _Aramas_ for contemporary Jains.\n*   **Umamaheswaram** (near Amaravati/Amrabad, the birthplace of the Vishnukunds), **Yeleswaram caves**, and **Alampuram** shone as prominent Saiva-Shakti temple sites, reflecting the Vishnukunds'' devotion to Siva as indicated by titles like _''parama maheswaras''_ and by the word \"Sriparvata\" on their coins. At Umamaheswaram, a Sivalinga carved by the Pallavas and a war-drum (_nagara bheri_) arranged by the Vishnukunds survive even today. Among the two cave temples at **Saleswaram**, an inscription in Brahmi script reads _''viswesa kakkalesa''_. Alampuram, in existence from Ikshvaku times, became famous for **Bala Brahmeswara** and the temple of **Jogulamba**; the **Nava Brahma** temples there were built by kings who came after the Vishnukunds. Cave temples of Vishnukund times are also found at **Bhairava Kona**, on the border of Prakasam and Nellore districts.\n*   In the surroundings of Vijayawada — another Vishnukund capital area — multi-storeyed Buddhist _arama-viharas_ were carved and built at **Undavalli, Mogalrajapuram**, and **Indrakeeladri** hills. The inscription _''Sri Utpatti Pidugu''_ is found on their walls or beneath their pillars, and similar writings appear at the cave temples of Saleswaram and Pandavulagutta in Warangal district. Some historians believe these writings, made after Saivites drove out Buddhists and Jains, name the society of architects and sculptors; the existence of such a society of architects and sculptors is further evidenced by the Telugu word _''Toluchuvandlu''_ found at Keesaragutta.", "free": false}, {"partNumber": 11, "conceptId": "telangana-history-en-chapter4-vishnukundis-p11", "partName": "Summary", "bodyMd": "The Vishnukunds ruled the entire Telugu country north of the Krishna river for more than two hundred years. During their long rule they introduced Hindu-based culture in place of the earlier composite (Buddhist-influenced) culture, and set an example for the dynasties that followed — their styles of architecture and sculpture were adopted by the Pallavas in the south and the Chalukyas in the west. \n\nThat the most popular later kings, the Kakatiyas, took Madhava Varma II, the Vishnukund king, as their dynastic founder speaks to the splendour of Vishnukund administration. Even as they followed Vedic religion and performed sacrifices and rituals, they also patronized Buddhism and Jainism and made donations freely to their organisations and monks, reflecting a policy of religious toleration. Through their administrative splendour, literary patronage, and establishment of _ghatikas_ at important centres, the Vishnukunds — the first royal dynasty to begin their political career in Telangana — secured eminence for their region and peace and prosperity for their people.", "free": false}]' WHERE chapter_slug = 'telangana-history-en-chapter4-vishnukundis';
